begin
  if auth.uid() is null and tg_op = 'UPDATE' then
    raise exception 'A signed-in actor is required' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.status is not distinct from old.status
     and new.assigned_to is not distinct from old.assigned_to
     and new.resolution is not distinct from old.resolution then
    return new;
  end if;
  insert into public.request_events(request_id, actor_id, status, assigned_name, resolution)
  values (new.id, coalesce(auth.uid(), new.user_id), new.status,
    (select display_name from public.service_staff where user_id = new.assigned_to),
    new.resolution);
  return new;
end;

begin
  if not private.is_service_staff() then
    raise exception 'Only service staff can process requests' using errcode = '42501';
  end if;
  if old.status = 'closed' then
    raise exception 'Closed requests cannot be changed' using errcode = '23514';
  end if;
  if new.status <> old.status and not (
    (old.status = 'new' and new.status = 'in_progress') or
    (old.status = 'in_progress' and new.status = 'closed')
  ) then
    raise exception 'Requests must move from new to in progress to closed' using errcode = '23514';
  end if;
  if new.status in ('in_progress', 'closed') and new.assigned_to is null then
    raise exception 'Assign a staff member before starting work' using errcode = '23514';
  end if;
  if new.assigned_to is not null and not exists (
    select 1 from public.service_staff
    where user_id = new.assigned_to and is_active
  ) then
    raise exception 'Assign an active staff member before processing the request' using errcode = '23514';
  end if;
  new.resolution := nullif(btrim(new.resolution), '');
  if new.status = 'closed' and (new.resolution is null or length(new.resolution) < 10) then
    raise exception 'Describe the completed work in at least 10 characters' using errcode = '23514';
  end if;
  if new.status <> 'closed' and new.resolution is not null then
    raise exception 'A resolution is recorded when closing the request' using errcode = '23514';
  end if;
  new.updated_at := clock_timestamp();
  new.closed_at := case when new.status = 'closed' then new.updated_at else null end;
  return new;
end;

declare
  owner_id uuid := auth.uid();
  stored_request public.service_requests%rowtype;
begin
  if owner_id is null then
    raise insufficient_privilege using message = 'Authentication required';
  end if;
  if p_operation_key is null then
    raise invalid_parameter_value using message = 'Submission key required';
  end if;

  select * into stored_request from public.service_requests
    where user_id = owner_id and operation_key = p_operation_key;
  if not found then
    insert into public.service_requests
      (user_id, operation_key, site, system, description, priority)
    values (owner_id, p_operation_key, p_site, p_system, p_description, p_priority)
    on conflict (user_id, operation_key) do nothing
    returning * into stored_request;

    if not found then
      -- A concurrent insert may have committed after the previous snapshot.
      -- This separate statement gets a fresh snapshot at READ COMMITTED.
      select * into stored_request from public.service_requests
        where user_id = owner_id and operation_key = p_operation_key;
      if not found then
        raise serialization_failure using message = 'Retry the same submission';
      end if;
    end if;
  end if;

  if stored_request.site is distinct from p_site
    or stored_request.system is distinct from p_system
    or stored_request.description is distinct from p_description
    or stored_request.priority is distinct from p_priority then
    raise sqlstate 'PT409' using message = 'Submission already saved with different details';
  end if;
  -- A replay never updates the row or emits another creation event.
  return next stored_request;
end;

begin
  insert into public.profiles (id, full_name)
  values (
    new.id,
    new.raw_user_meta_data ->> 'full_name'
  )
  on conflict (id) do nothing;

  return new;
end;

declare
  saved_request public.service_requests%rowtype;
begin
  if not private.is_service_staff() then
    raise insufficient_privilege using message = 'Only service staff can process requests';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise invalid_parameter_value using message = 'Expected version required';
  end if;
  update public.service_requests
    set expected_version = p_expected_version,
        assigned_to = p_assigned_to,
        status = p_status,
        resolution = p_resolution
    where id = p_request_id
    returning * into saved_request;
  if not found then
    raise sqlstate 'PT404' using message = 'Request not available';
  end if;
  return next saved_request;
end;

DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
